CREATE TABLE "ORDER_ITEMS" (
    "ID" NUMBER DEFAULT "TESTSCHEMA"."ISEQ$$_0000003".nextval NOT NULL,
    "ORDER_ID" NUMBER NOT NULL,
    "PRODUCT_NAME" VARCHAR2(100 BYTE) NOT NULL,
    "QUANTITY" NUMBER NOT NULL,
    "UNIT_PRICE" NUMBER(10,2) NOT NULL
);
ALTER TABLE "ORDER_ITEMS" ADD CONSTRAINT "SYS_C0000003" PRIMARY KEY (ID);
CREATE OR REPLACE TRIGGER TRG_UPDATE_ORDER_TOTAL
AFTER INSERT OR UPDATE OR DELETE ON ORDER_ITEMS
FOR EACH ROW
DECLARE
    V_ORDER_ID NUMBER;
    V_TOTAL NUMBER(10, 2);
BEGIN
    -- Get order ID
    IF INSERTING OR UPDATING THEN
        V_ORDER_ID := :NEW.ORDER_ID;
    ELSE
        V_ORDER_ID := :OLD.ORDER_ID;
    END IF;
    
    -- Calculate new total
    SELECT NVL(SUM(QUANTITY * UNIT_PRICE), 0) INTO V_TOTAL
    FROM ORDER_ITEMS
    WHERE ORDER_ID = V_ORDER_ID;
    
    -- Update order total
    UPDATE ORDERS SET TOTAL_AMOUNT = V_TOTAL WHERE ID = V_ORDER_ID;
END;

ALTER TABLE "ORDER_ITEMS" ADD CONSTRAINT "FK_ORDER_ITEM" FOREIGN KEY ("ORDER_ID") REFERENCES "ORDERS" ("ID") ON DELETE CASCADE;
ALTER TABLE "CUSTOMERS" ADD CONSTRAINT "FK_PREFERRED_ORDER" FOREIGN KEY ("PREFERRED_ORDER_ID") REFERENCES "ORDERS" ("ID");
ALTER TABLE "ORDERS" ADD CONSTRAINT "FK_CUSTOMER" FOREIGN KEY ("CUSTOMER_ID") REFERENCES "CUSTOMERS" ("ID");
